mapper.update:
/*selectMasterWmStAssmblDirectionsCreationPopInsertWmsAssemb*/ INSERT INTO WMSASSEMB( AS_NO ,BOM_ID ,SUB_ID ,STATUS ,WAREHOUSE_CODE ,BOM_QTY ,SUB_QTY ,BOM_AMT ,SUB_PRICE ,SUB_AMT ,ADD_DATE ,ADD_USER_ID ,ASSEMB_FLAG ,WORK_TYPE ) SELECT #{ASNO} AS_NO, BOM_ID, SUB_ID, 'C' STATUS, ST.WAREHOUSE_CODE, #{ASSEMBLY_QTY} BOM_QTY, BOM.QTY*#{ASSEMBLY_QTY} SUB_QTY, ( SELECT SUM(SST.STC_SELLER_PRICE*SBOM.QTY*#{ASSEMBLY_QTY}) FROM KEPBOFM SBOM, WMSSTCK SST WHERE SBOM.BOM_ID = #{BUYER_ITEM_NO} AND SBOM.SUB_ID = SST.STDCATLG_ID AND SST.PROCESS_TYPE = '1' AND SST.AGENT = 'KRKORE0001' AND SST.WAREHOUSE_CODE = #{st_warehouse_code} AND SST.STATUS <> 'D' AND SBOM.STATUS <> 'D' ) BOM_AMT ,
ST.STC_SELLER_PRICE SUB_PRICE, ST.STC_SELLER_PRICE*BOM.QTY* #{ASSEMBLY_QTY} SUB_AMT, TO_CHAR(SYSDATE,'YYYYMMDD') ADD_DATE, #{st_user_id} ADD_USER_ID, 'N' ASSEMB_FLAG, #{st_assembly_type} WORK_TYPE
FROM KEPBOFM BOM, WMSSTCK ST WHERE BOM.BOM_ID = #{BUYER_ITEM_NO} AND BOM.SUB_ID = ST.STDCATLG_ID AND ST.PROCESS_TYPE = '1' AND ST.AGENT = 'KRKORE0001' AND ST.STATUS <> 'D' AND ST.WAREHOUSE_CODE = #{st_warehouse_code} AND ST.STATUS <> 'D' AND BOM.STATUS <> 'D'

mapper.select:

		/*selectMasterWmStAssmblDirectionsCreationPopChangeList*/
		        SELECT SUB_ID, SUM(QTY)AS SUM_QTY FROM KEPBOFM 
         WHERE BOM_ID =#{st_bomid}
        GROUP BY SUB_ID

/*selectMasterWmStAssmblDirectionsCreationPopList2*/ SELECT BOM.SUB_ID, MAX(IT.DESCRIPTION_LOC) DESCRIPTION_LOC, MAX(IT.SPECIFICATION) SPECIFICATION, MAX(IT.UNIT_MEASURE) UNIT_MEASURE, MAX(ST.AVAIL_QTY) AVAIL_QTY, MAX(ST.STC_SELLER_PRICE) STC_SELLER_PRICE, MAX(IT.MAKER_NAME) MAKER_NAME, MAX(IT.ORIGIN_CODE) ORIGIN_CODE FROM ICOMBYIT IT, WMSSTCK ST , KEPBOFM BOM WHERE IT.BUYER = ST.WAREHOUSE_CODE AND IT.BUYER_ITEM_NO = ST.STDCATLG_ID AND IT.STATUS <> 'D' AND ST.STATUS <> 'D' AND BOM.STATUS <> 'D' AND ST.PROCESS_TYPE = '1' AND BOM.SUB_ID = IT.BUYER_ITEM_NO AND ST.WAREHOUSE_CODE = #{st_warehouse_code} AND BOM.BOM_ID IN
#{st_sel_item_no}
GROUP BY BOM.SUB_ID
